/**
 * Unified geography — one filter for country, state, city and region.
 */
export interface GeoFilter {
  readonly places: readonly GeoPlace[];
}

export type GeoLevel =
  | "country"
  | "state"
  | "city"
  | "region";

/**
 * One place, pinned to a level and optionally to an entity side.
 */
export interface GeoPlace {
  /**
   * Required: there is no place-name -> level resolver on the request path, so
   * `berlin` is only a city because you said so.
   */
  readonly level: GeoLevel;
  /**
   * Exclude this place instead of requiring it.
   */
  readonly negate?: boolean;
  readonly scope?: GeoScope;
  readonly value: string;
}

/**
 * Whose location a place constrains. `subject` (default) is whatever record
 * type is being searched. `company`/`person` force that side regardless of the
 * search target, which is what lets a contact search constrain the parent
 * company's HQ.
 */
export type GeoScope =
  | "subject"
  | "company"
  | "person";

/**
 * The countries a company employs in, from per-country headcount. Lowercase
 * ISO3 codes, largest headcount first. ``hq_country`` is ``None`` when the HQ
 * country name has no ISO3 entry in the filter's name table.
 */
export interface GlobalPresence {
  readonly countries: readonly string[];
  readonly country_count?: number | null;
  readonly hq_country?: string | null;
  readonly [key: string]: unknown;
}

/**
 * Country-footprint filter: where a company has people, not where it is
 * headquartered. `countries` names the places: a country ("germany", ISO3
 * "deu") or a region ("EU", "APAC", "Nordics"), which any one of its member
 * countries satisfies. A company matches with at least `gte` (default 1) people
 * in ANY place named, or in EVERY place with `match_all` ("offices in Germany
 * and France"). With `min_countries` instead, it matches companies present in
 * at least that many countries. Prism refuses a place it does not know with
 * `request.invalid`.
 */
export interface GlobalPresenceFilter {
  /**
   * Countries (names or ISO3 codes) or regions (EU, APAC, Nordics, DACH, LATAM,
   * ...).
   */
  readonly countries?: readonly string[];
  /**
   * Per-country headcount floor.
   */
  readonly gte?: number | null;
  readonly lte?: number | null;
  /**
   * People in EVERY place named, not any one.
   */
  readonly match_all?: boolean;
  readonly min_countries?: number | null;
}

