/**
 * Include / exclude over a term-like field.
 */
export interface TermsFilter {
  readonly exclude?: readonly string[];
  readonly include?: readonly string[];
  /**
   * The `include` values, one list per thing named: any value in a list
   * satisfies it, and `match_all` requires every LIST rather than every value.
   * `technology` resolves a product onto every name the index stores it under
   * and reports them this way, so a resolved filter sent back keeps "both X and
   * Y". `include` stays the source of truth: a value removed from it leaves its
   * group.
   */
  readonly include_groups?: readonly (readonly string[])[] | null;
  /**
   * True requires every `include` value (AND). False (default) is OR.
   */
  readonly match_all?: boolean;
}

/**
 * Free-text field match with an exact-match escape hatch. `exact=False`
 * (default) runs an analyzed phrase match. `exact=True` targets the `.keyword`
 * subfield instead — use it when you have a canonical string and want no
 * analysis.
 */
export interface TextFilter {
  readonly exact?: boolean;
  readonly exclude?: readonly string[];
  readonly include?: readonly string[];
}

